  const token=randomUUID(),server=createServer({instanceToken:token,fullAccess:true,unconfinedBoot:true,coding:owner,worktrees:manager,gitWorkflow:workflow,hub:{stop:async()=>{},close:async()=>{}}});server.listen(0,'127.0.0.1');await once(server,'listening');const base=`http://127.0.0.1:${server.address().port}`,route='/api/tools/git';
