  const snapshot=async()=>(await call({action:'inspect',cwd:project})).snapshot;
  const prepare=async(request,s=undefined)=>{s??=await snapshot();return call({action:'prepare',cwd:project,snapshotId:s.id,requestId:randomUUID(),request:typeof request==='function'?request(s):request});};
  const execute=async p=>{assert(p.plan,JSON.stringify(p));await call({action:'execute',planId:p.plan.id,requestId:randomUUID()},409);return call({action:'execute',planId:p.plan.id,requestId:p.plan.requestId});};
  const stage=s=>({kind:'stage',entryIds:[s.entries.find(e=>e.path==='file').id]});
