    r=await execute(await prepare(s=>({kind:'unstage',entryIds:[s.entries.find(e=>e.path==='file').id]})));assert.equal(r.state,'completed',r.message);assert.equal(await text(project,['show',':file']),'BASE');
    assert.equal((await execute(await prepare(stage))).state,'completed');const parent=await text(project,['rev-parse','HEAD']);
    r=await execute(await prepare({kind:'commit',message:'Full Access verified commit',authorName:'Fixture',authorEmail:'fixture@example.invalid'}));assert.equal(r.state,'completed',r.message);assert.equal(await text(project,['rev-parse','HEAD^']),parent);assert.equal(await text(project,['show','HEAD:file']),'EDITED');
    r=await execute(await prepare({kind:'createBranch',name:'full-access/verified'}));assert.equal(r.state,'completed',r.message);assert.equal(await text(project,['rev-parse','full-access/verified']),await text(project,['rev-parse','HEAD']));assert.equal(await text(project,['symbolic-ref','--short','HEAD']),'main');
    assert.equal(await readFile(join(project,'file'),'utf8'),'EDITED\n');
    await writeFile(join(project,'file'),'REVIEWED\n');const p=await prepare(stage),index=await readFile(join(project,'.git/index'));await writeFile(join(project,'file'),'NEWER OWNER EDIT\n');r=await execute(p);assert.equal(r.state,'stale');assert.deepEqual(await readFile(join(project,'.git/index')),index);assert.equal(await readFile(join(project,'file'),'utf8'),'NEWER OWNER EDIT\n');
    const locked=await prepare(stage);await writeFile(join(project,'.git/index.lock'),'FOREIGN LOCK',{flag:'wx'});try{r=await execute(locked);assert.notEqual(r.state,'completed');assert.equal(await readFile(join(project,'.git/index.lock'),'utf8'),'FOREIGN LOCK');assert.deepEqual(await readFile(join(project,'.git/index')),index);}finally{await rename(join(project,'.git/index.lock'),join(root,'full-access-foreign-lock'));}
    for(const policy of [null,{kind:'unknown',target:()=>project}])await assert.rejects(owner.reserveProjectMutation(async()=>[project],policy),/Full Access boot/);
    await assert.rejects(owner.reserveProjectMutation(async()=>[project],{kind:'stage',target:()=>root}),/target|lease/i);
    await assert.rejects(owner.reserveProjectMutation(async()=>[project],{kind:'stage',target:()=>project,extra:true}),/Invalid trusted/);
    const current=await snapshot();for(const kind of ['unknown'])await call({action:'prepare',cwd:project,snapshotId:current.id,requestId:randomUUID(),request:{kind,name:'full-access/verified'}},409);
    const stopped=await prepare(stage);assert(stopped.plan);await call({action:'stop',requestId:stopped.plan.requestId});await call({action:'execute',planId:stopped.plan.id,requestId:stopped.plan.requestId},409);
    assert.equal((await fetch(base+route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'prepare',cwd:project,snapshotId:current.id,requestId:randomUUID(),request:{kind:'stage',entryIds:current.entries.map(e=>e.id)}})})).status,403);
    assert.equal(await text(project,['symbolic-ref','--short','HEAD']),'main');assert.equal(await readFile(join(project,'file'),'utf8'),'NEWER OWNER EDIT\n');
