await check('branch inventory limit does not disable existing staging',async()=>{const f=await switchFixture('inventory-limit');await Promise.all(Array.from({length:513},(_,i)=>writeFile(join(f.project,'.git/refs/heads/extra-'+i),f.old+'\n')));await writeFile(join(f.project,'keep'),'local change');const s=await f.snapshot();assert.deepEqual(s.branches,[]);assert.match(s.branchWarning,/512/);assert(!s.warning,s.warning);const p=await f.api.handle({action:'prepare',cwd:f.project,snapshotId:s.id,requestId:randomUUID(),request:{kind:'stage',entryIds:[s.entries.find(x=>x.path==='keep').id]}});assert.equal((await f.run(p)).state,'completed');await f.api.close();});
await check('unconfirmed checkout exit retains recovery and the shared reservation',async()=>{let api,p,stopping,armed=false,held=0;const f=await switchFixture('unconfirmed-close',{reserveMutation:async resolve=>{await resolve();held++;return {release(){held--;}};},spawnProcess:(file,args,options)=>{const child=spawn(file,args,options);if(armed&&args.includes('switch')){const emit=child.emit.bind(child);child.emit=(event,...values)=>event==='close'?true:emit(event,...values);child.once('exit',()=>{stopping=api.handle({action:'stop',requestId:p.plan.requestId});});}return child;}});api=f.api;p=await f.plan();assert(p.plan,JSON.stringify(p));armed=true;const r=await f.run(p);assert.equal(r.state,'unknown',JSON.stringify(r));assert.equal((await stopping).state,'unknown');assert.equal(held,1);assert((await lstat(join(f.dataDir,'GitWorkflow',p.plan.id,'original-index'))).isFile());await assert.rejects(f.snapshot(),/unconfirmed/);await api.close();assert.equal(held,1);});


await check('late symbolic source identity is rejected even at the same commit',async()=>{const f=await switchFixture('symbolic-source');await raw(f.project,['update-ref','refs/heads/alias',f.old]);const p=await f.plan();await raw(f.project,['symbolic-ref','refs/heads/main','refs/heads/alias']);const r=await f.run(p);assert.notEqual(r.state,'completed',JSON.stringify(r));assert.equal(await readFile(join(f.project,'.git/HEAD'),'utf8'),'ref: refs/heads/main\n');assert.equal(await readFile(join(f.project,'change'),'utf8'),'BASE\n');await f.api.close();});


await check('failed ref transaction cancels its still-running checkout before releasing reservation',async()=>{let armed=false,outer,held=0;const pids=[],f=await switchFixture('parent-failure',{reserveMutation:async resolve=>{await resolve();held++;return {release(){for(const pid of pids)assert.throws(()=>process.kill(-pid,0));held--;}};},spawnProcess:(file,args,options)=>{const child=spawn(file,args,options);if(armed&&args.includes('update-ref')){outer=child.pid;pids.push(child.pid);}if(armed&&args.includes('switch')){pids.push(child.pid);process.kill(-child.pid,'SIGSTOP');process.kill(-outer,'SIGTERM');}return child;}});const p=await f.plan();assert(p.plan,JSON.stringify(p));const oldIndex=await readFile(join(f.project,'.git/index'));armed=true;const started=Date.now(),r=await f.run(p);assert.equal(r.state,'unknown',JSON.stringify(r));assert.deepEqual(await readFile(join(f.project,'.git/index')),oldIndex);assert.equal(await readFile(join(f.project,'.git/HEAD'),'utf8'),'ref: refs/heads/main\n');assert(Date.now()-started<6000,'Checkout must be cancelled promptly when its ref transaction exits.');assert.equal(held,0);await f.api.close();});


