await check('actual prepared process exit fences publication before delayed stream close',async()=>{
  let armed=false,parent,parentExited=false,parentClosed=false,held=0;const pids=[],f=await switchFixture('parent-exit-held-close',{reserveMutation:async resolve=>{await resolve();held++;return {release(){assert(parentClosed,'Reservation requires parent close confirmation.');for(const pid of pids)assert.throws(()=>process.kill(-pid,0));held--;}};},spawnProcess:(file,args,options)=>{const child=spawn(file,args,options);if(armed&&args.includes('update-ref')){parent=child;pids.push(child.pid);child.once('exit',()=>{parentExited=true;});const emit=child.emit.bind(child);child.emit=(event,...values)=>{if(event==='close'){setTimeout(()=>{parentClosed=true;emit(event,...values);},2000);return true;}return emit(event,...values);};}if(armed&&args.includes('switch')){pids.push(child.pid);process.kill(-child.pid,'SIGSTOP');process.kill(parent.pid,'SIGTERM');setTimeout(()=>{try{process.kill(-child.pid,'SIGCONT');}catch(e){if(e.code!=='ESRCH')throw e;}},500);}return child;}});
  const p=await f.plan();assert(p.plan,JSON.stringify(p));const index=await readFile(join(f.project,'.git/index')),head=await readFile(join(f.project,'.git/HEAD'));armed=true;const r=await f.run(p);assert(parentExited);assert.equal(r.state,'unknown',JSON.stringify(r));assert.deepEqual(await readFile(join(f.project,'.git/index')),index,'Actual parent death must fence real index publication even before close.');assert.deepEqual(await readFile(join(f.project,'.git/HEAD')),head);assert.equal(held,0);await f.api.close();
});


await check('lost parent authority during checkout verification prevents even spawning checkout',async()=>{
  let armed=false,parent,releaseVerify,enteredVerify,parentExit,checkoutSpawns=0;const gate=new Promise(r=>releaseVerify=r),entered=new Promise(r=>enteredVerify=r),exited=new Promise(r=>parentExit=r),f=await switchFixture('parent-before-spawn',{spawnProcess:(file,args,options)=>{const child=spawn(file,args,options);if(armed&&args.includes('update-ref')){parent=child;child.once('exit',parentExit);}if(armed&&args.includes('switch'))checkoutSpawns++;return child;}}),runner=f.api.checkoutRunner,verify=runner.verify.bind(runner),run=runner.run.bind(runner);let hold=false;runner.run=(args,options)=>{hold=args.includes('switch');return run(args,options);};runner.verify=async()=>{if(hold){enteredVerify();await gate;}return verify();};
  const p=await f.plan();assert(p.plan,JSON.stringify(p));armed=true;const pending=f.run(p);await entered;process.kill(parent.pid,'SIGTERM');await exited;releaseVerify();const r=await pending;assert.equal(r.state,'unknown',JSON.stringify(r));assert.equal(checkoutSpawns,0,'A dead transaction cannot admit a new checkout after asynchronous executable verification.');assert.equal(await readFile(join(f.project,'change'),'utf8'),'BASE\n');assert.equal(await readFile(join(f.project,'.git/HEAD'),'utf8'),'ref: refs/heads/main\n');await f.api.close();
});

await check('file-focused patches preserve exact paths, sides, limits and read-only inspection',async()=>{
  const project=join(root,'file-focused'),dataDir=join(root,'file-focused-data');await mkdir(project);await raw(project,['init','-b','main']);
  const names=['space name.txt','quote"tab\tline\n😀.txt','back\\slash.txt','control\x01.txt','-leading.txt','العربية.txt'];
  for(const name of [...names,'delete.txt','mode.sh'])await writeFile(join(project,name),'HEADER\n\nBASE\nFOOTER\n');await writeFile(join(project,'binary.bin'),Buffer.from([0,1,2,3]));await raw(project,['add','--all']);await raw(project,['-c','user.name=Fixture','-c','user.email=fixture@example.invalid','commit','-m','base']);
  for(const name of names)await writeFile(join(project,name),'HEADER\n\nSTAGED <img src=x onerror=alert(1)>\nFOOTER\n');await rm(join(project,'delete.txt'));await raw(project,['add','--all']);
  for(const name of names)await writeFile(join(project,name),'HEADER\n\nWORKING <script>never execute</script>\nFOOTER\n');await chmod(join(project,'mode.sh'),0o755);await writeFile(join(project,'binary.bin'),Buffer.from([0,9,8,7]));await writeFile(join(project,'untracked.txt'),'KEEP UNTRACKED\n');await writeFile(join(project,'new العربية😀.txt'),'FIRST <img src=x onerror=alert(1)>\nثاني😀');await writeFile(join(project,'untracked-empty.txt'),'');await writeFile(join(project,'untracked-binary.bin'),Buffer.from([0,1,2]));await writeFile(join(project,'untracked-invalid.txt'),Buffer.from([0xff,0xfe]));await writeFile(join(project,'untracked-large.txt'),'L'.repeat(160001));await symlink('literal-target',join(project,'untracked-link'));
  for(const [key,value] of [['core.quotePath','true'],['diff.noprefix','true'],['diff.mnemonicPrefix','true'],['diff.renames','true'],['color.ui','always'],['diff.suppressBlankEmpty','true']])await raw(project,['config',key,value]);
  const before=await readFile(join(project,'.git/index')),api=new GitWorkflow({dataDir});let diffCalls=0;const run=api.run.bind(api);api.run=(r,args,...rest)=>{if(args.includes('diff'))diffCalls++;return run(r,args,...rest);};
  const s=(await api.handle({action:'inspect',cwd:project})).snapshot;
  assert(Array.isArray(s.fileDiffs),'File-focused inspection must expose patches linked to the exact snapshot entry IDs');assert.equal(s.fileDiffs.length,s.entries.length);assert.equal(diffCalls,2,'File count must not add Git subprocesses');assert.equal(new Set(s.fileDiffs.map(row=>row.entryId)).size,s.entries.length);
  for(const name of names){const entry=s.entries.find(row=>row.path===name),view=s.fileDiffs.find(row=>row.entryId===entry.id);assert.match(view.workingTree,/WORKING <script>/);assert(view.workingTree.includes('\n \n'),'Blank context lines must keep the canonical context prefix despite repository config');assert(!view.workingTree.includes('+STAGED'));assert.match(view.staged,/\+STAGED <img/);assert(!view.staged.includes('+WORKING'));assert(!view.workingTree.includes('\u001b'),'Display output is never colored by repository config');}
  const view=name=>s.fileDiffs.find(row=>row.entryId===s.entries.find(row=>row.path===name).id);
  assert.match(view('delete.txt').staged,/deleted file mode/);assert.match(view('binary.bin').workingTree,/GIT binary patch/);assert.match(view('mode.sh').workingTree,/new mode 100755/);assert.match(view('untracked.txt').workingTree,/@@ -0,0 \+1,1 @@\n\+KEEP UNTRACKED\n/);assert.equal(view('untracked.txt').staged,'');assert.match(view('new العربية😀.txt').workingTree,/\+FIRST <img src=x onerror=alert\(1\)>\n\+ثاني😀\n\\ No newline at end of file/);assert.match(view('untracked-empty.txt').workingTree,/Empty file/);for(const name of ['untracked-binary.bin','untracked-invalid.txt'])assert.match(view(name).workingTree,/binary|UTF-8/);assert.match(view('untracked-large.txt').workingTree,/160000-byte preview limit/);assert(!view('untracked-large.txt').workingTree.includes('LLLLL'));assert.match(view('untracked-link').workingTree,/new file mode 120000/);assert.match(view('untracked-link').workingTree,/\+literal-target\n\\ No newline at end of file/);
  assert.deepEqual(await readFile(join(project,'.git/index')),before);for(const name of names)assert.equal(await readFile(join(project,name),'utf8'),'HEADER\n\nWORKING <script>never execute</script>\nFOOTER\n');
  api.run=async(r,args,...rest)=>{const result=await run(r,args,...rest);if(args.includes('diff')&&!args.includes('--cached'))result.stdout=result.stdout.replace(/^diff --git .*$/m,'diff --git a/UNKNOWN b/UNKNOWN');return result;};const unknown=(await api.handle({action:'inspect',cwd:project})).snapshot;assert.equal(unknown.fileDiffs,null,'An unrecognized header retains the aggregate instead of guessing the path');assert.match(unknown.diff,/UNKNOWN/);api.run=run;
  await writeFile(join(project,names[0]),'LONG_DIFF\n'.repeat(30000));const large=(await api.handle({action:'inspect',cwd:project})).snapshot;assert(large.truncated);assert.equal(large.fileDiffs,null,'Truncated output cannot pretend omitted files have no changes');assert.match(large.diff,/Diff display truncated/);assert(JSON.stringify(large).length<1000000);await api.close();
});

await check('file-focused untracked disappearance retains an explicit unavailable preview',async()=>{
  const project=join(root,'file-focused-disappearing');await mkdir(project);await raw(project,['init','-b','main']);await writeFile(join(project,'tracked'),'BASE\n');await raw(project,['add','tracked']);await raw(project,['-c','user.name=Fixture','-c','user.email=fixture@example.invalid','commit','-m','base']);await writeFile(join(project,'disappears.txt'),'temporary\n');
  const index=await readFile(join(project,'.git/index')),api=new GitWorkflow({dataDir:join(root,'file-focused-disappearing-data')}),file=api.file.bind(api);api.file=async(r,path)=>{if(path==='disappears.txt')await rm(join(project,path));return file(r,path);};
  const snapshot=(await api.handle({action:'inspect',cwd:project})).snapshot;assert(!snapshot.warning,snapshot.warning);const entry=snapshot.entries.find(row=>row.path==='disappears.txt');assert(entry);assert.match(snapshot.fileDiffs.find(row=>row.entryId===entry.id).workingTree,/no longer available/);assert.deepEqual(await readFile(join(project,'.git/index')),index);assert.equal(await readFile(join(project,'tracked'),'utf8'),'BASE\n');await api.close();
});

await check('file-focused preview budget preserves a previously valid large snapshot',async()=>{
  const entries=Array.from({length:2000},(_,i)=>({id:randomUUID(),path:'folder/'+('x'.repeat(350))+'-'+i,index:'?',worktree:'?',canStage:true,canUnstage:false}));
  const state={id:randomUUID(),r:{repositoryId:'r',commonRepositoryId:'c',cwd},branch:'main',head:'a'.repeat(40),entries,diff:'',truncated:false,fileDiffs:entries.map(entry=>({entryId:entry.id,workingTree:'',staged:''}))};
  const before={...g.publicSnapshot(state)};delete before.fileDiffs;assert(JSON.stringify(before).length<1000000);assert(JSON.stringify({...before,fileDiffs:state.fileDiffs}).length>1000000,'Case must cross the existing frontend response cap');const snapshot=g.publicSnapshot(state);assert(JSON.stringify(snapshot).length<=1000000,'Optional display data must not break a previously valid snapshot');assert(snapshot.fileDiffs==null);assert.deepEqual(snapshot.entries,entries);
});

